<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class TeachingLoadController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head'),403);}
 public function index(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$loads=DB::table('teaching_load_plans as l')->leftJoin('study_groups as g','g.id','=','l.study_group_id')->leftJoin('teachers as t','t.id','=','l.teacher_id')->leftJoin('subjects as s','s.id','=','l.subject_id')->leftJoin('study_types as st','st.id','=','l.study_type_id')->leftJoin('rooms as rm','rm.id','=','l.room_id')->where('l.academic_period_id',$p->id)->select('l.*','g.name as group_name','t.last_name','t.first_name','s.name as subject_name','st.name as study_type_name','rm.name as room_name')->orderBy('g.name')->orderBy('s.name')->get();$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();$teachers=DB::table('teachers')->where('active',1)->orderBy('last_name')->get();$subjects=DB::table('subjects')->orderBy('name')->get();$types=DB::table('study_types')->orderBy('name')->get();$rooms=DB::table('rooms')->orderBy('name')->get();return view('academic-office.loads',compact('p','loads','groups','teachers','subjects','types','rooms'));}
 public function store(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['study_group_id'=>'required|exists:study_groups,id','teacher_id'=>'required|exists:teachers,id','subject_id'=>'required|exists:subjects,id','study_type_id'=>'required|exists:study_types,id','room_id'=>'nullable|exists:rooms,id','hours_total'=>'required|numeric|min:0.1|max:9999','hours_week'=>'nullable|numeric|min:0|max:999','note'=>'nullable|string|max:2000']);$source=(DB::table('teaching_load_plans')->where('academic_period_id',$p->id)->max('source_load_id')??0)+1;DB::table('teaching_load_plans')->insert($d+['academic_period_id'=>$p->id,'source_load_id'=>$source,'status'=>'active','created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Нагрузка добавлена.');}
 public function update(Request $r,$id){$this->ok($r);$x=DB::table('teaching_load_plans')->find($id);abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);$d=$r->validate(['teacher_id'=>'required|exists:teachers,id','room_id'=>'nullable|exists:rooms,id','hours_total'=>'required|numeric|min:0.1|max:9999','hours_week'=>'nullable|numeric|min:0|max:999','note'=>'nullable|string|max:2000']);DB::table('teaching_load_plans')->where('id',$id)->update($d+['updated_at'=>now()]);return back()->with('success','Нагрузка обновлена.');}
 public function destroy(Request $r,$id){$this->ok($r);$x=DB::table('teaching_load_plans')->find($id);abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);DB::table('teaching_load_plans')->where('id',$id)->delete();return back()->with('success','Строка нагрузки удалена.');}
 public function export(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$loads=DB::table('teaching_load_plans')->where('academic_period_id',$p->id)->where('status','active')->get();$missing=[];foreach($loads as $x){foreach(['study_group_id'=>'группа','teacher_id'=>'преподаватель','subject_id'=>'дисциплина','study_type_id'=>'вид занятия'] as $f=>$n){$table=['study_group_id'=>'study_groups','teacher_id'=>'teachers','subject_id'=>'subjects','study_type_id'=>'study_types'][$f];if(!$x->$f||DB::table($table)->where('id',$x->$f)->whereNull('source_id')->exists())$missing[]=$n.' в строке '.$x->id;}}if($missing)return back()->withErrors(['export'=>'Экспорт невозможен: отсутствуют Rector source_id: '.implode(', ',array_unique($missing))]);
 $xml=new \SimpleXMLElement('<?xml version="1.0" encoding="UTF-8"?><rector_export/>');$xml->addChild('format')->addChild('version','1.7');$term=$xml->addChild('term');$term->addChild('begin_date',date('d.m.Y',strtotime($p->starts_on)));$term->addChild('end_date',date('d.m.Y',strtotime($p->ends_on)));$root=$xml->addChild('loads');foreach($loads as $x){$l=$root->addChild('load');$l->addChild('id',$x->source_load_id);$l->addChild('hours_total',$x->hours_total);$l->addChild('hours_week',$x->hours_week??'');$kl=$l->addChild('klass_id_list');$kl->addChild('int',DB::table('study_groups')->where('id',$x->study_group_id)->value('source_id'));$gs=$l->addChild('groups');$g=$gs->addChild('group');$g->addChild('teacher_id',DB::table('teachers')->where('id',$x->teacher_id)->value('source_id'));$g->addChild('subject_id',DB::table('subjects')->where('id',$x->subject_id)->value('source_id'));$g->addChild('study_type_id',DB::table('study_types')->where('id',$x->study_type_id)->value('source_id'));if($x->room_id)$l->addChild('room_id',DB::table('rooms')->where('id',$x->room_id)->value('source_id'));}$dom=dom_import_simplexml($xml)->ownerDocument;$dom->formatOutput=true;$data=$dom->saveXML();$data=mb_convert_encoding($data,'Windows-1251','UTF-8');DB::table('rector_exchange_runs')->insert(['academic_period_id'=>$p->id,'user_id'=>$r->user()->id,'direction'=>'export','kind'=>'loads','filename'=>'rector-loads-'.$p->id.'.xml','sha256'=>hash('sha256',$data),'status'=>'done','stats'=>json_encode(['loads'=>$loads->count()],JSON_UNESCAPED_UNICODE),'created_at'=>now(),'updated_at'=>now()]);return response($data,200,['Content-Type'=>'application/xml; charset=windows-1251','Content-Disposition'=>'attachment; filename="rector-loads-'.$p->id.'.xml"']);}
}